class Solution {
public:
    long long maxNumber(long long n) {
        long long power = 1;
        while ((power << 1) <= n) {
            power <<= 1;
        }
        return power - 1;
    }
};

class Solution {
    public long maxNumber(long n) {
        long power = 1;
        while ((power << 1) <= n) {
            power <<= 1;
        }
        return power - 1;
    }
}

var maxNumber = function(n) {
    let power = 1n;
    const target = BigInt(n);
    while ((power << 1n) <= target) {
        power <<= 1n;
    }
    return Number(power - 1n);
};
